```c
static int mbedtls_x509_crt_parse_der_internal( mbedtls_x509_crt *chain,
                                                const unsigned char *buf,
                                                size_t buflen,
                                                int make_copy )
{
    int ret;
    mbedtls_x509_crt *crt = chain, *prev = NULL;

    if( crt == NULL || buf == NULL )
        return( MBEDTLS_ERR_X509_BAD_INPUT_DATA );

    while( crt->version != 0 && crt->next != NULL )
    {
        prev = crt;
        crt = crt->next;
    }

    if( crt->version != 0 && crt->next == NULL )
    {
        crt->next = mbedtls_calloc( 1, sizeof( mbedtls_x509_crt ) );
        if( crt->next == NULL )
            return( MBEDTLS_ERR_X509_ALLOC_FAILED );
        prev = crt;
        mbedtls_x509_crt_init( crt->next );
        crt = crt->next;
    }

    if( ( ret = x509_crt_parse_der_core( crt, buf, buflen, make_copy ) ) != 0 )
    {
        if( prev )
            prev->next = NULL;
        if( crt != chain )
            mbedtls_free( crt );
        return( ret );
    }

    return( 0 );
}
```

Key observation: `x509_crt_parse_der_core` calls `mbedtls_x509_crt_free(crt)` on error. After `mbedtls_x509_crt_free(crt)` returns:
- All internal allocations of `crt` are freed
- The cert struct is zeroed (`mbedtls_platform_zeroize`)
- `crt` itself is NOT freed (it's the head of the passed-in chain)

Then back in `mbedtls_x509_crt_parse_der_internal`:
- `prev->next = NULL` - but `crt->next` was already zeroed by `mbedtls_x509_crt_free`! 
- `mbedtls_free(crt)` - frees the struct

